import express, { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

const app = express();
app.use(express.json());

// Require secrets from the environment; fail fast if missing (no insecure fallbacks)
function requireEnv(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

// Cross-service authentication keys
const SERVICE_KEYS: Record<string, string> = {
  'mobile-gateway': requireEnv('MOBILE_GW_KEY'),
  'user-service': requireEnv('USER_SVC_KEY'),
  'admin-panel': requireEnv('ADMIN_KEY'),
};

const JWT_SECRET = requireEnv('JWT_SECRET');

interface ServiceToken {
  service: string;
  delegatedUser?: string;
  delegatedRole?: string;
  timestamp: number;
  nonce: string;
}

interface UserToken {
  userId: string;
  role: string;
  email: string;
}

// Verify HMAC signature from calling service
function verifyServiceHMAC(payload: string, signature: string, serviceId: string): boolean {
  const key = SERVICE_KEYS[serviceId];
  if (!key) return false;
  try {
    const expected = crypto.createHmac('sha256', key).update(payload).digest('hex');
    const expectedBuf = Buffer.from(expected, 'hex');
    const providedBuf = Buffer.from(signature, 'hex');
    // timingSafeEqual throws on length mismatch; guard to avoid crashes/DoS
    if (expectedBuf.length !== providedBuf.length) return false;
    return crypto.timingSafeEqual(expectedBuf, providedBuf);
  } catch {
    return false;
  }
}

// Parse and validate service-to-service token
function parseServiceToken(raw: string): ServiceToken | null {
  try {
    const parsed = JSON.parse(Buffer.from(raw, 'base64').toString('utf-8'));
    if (!parsed.service || !parsed.timestamp || !parsed.nonce) return null;
    // Reject tokens older than 5 minutes
    if (Date.now() - parsed.timestamp > 300000) return null;
    return parsed as ServiceToken;
  } catch {
    return null;
  }
}

// Middleware: authenticate either user JWT or service-to-service call
function authenticate(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers['authorization'];
  const serviceHeader = req.headers['x-service-token'] as string | undefined;
  const signatureHeader = req.headers['x-service-signature'] as string | undefined;

  if (serviceHeader && signatureHeader) {
    // Service-to-service authentication path
    const serviceToken = parseServiceToken(serviceHeader);
    if (!serviceToken) return res.status(401).json({ error: 'Invalid service token' });

    if (!verifyServiceHMAC(serviceHeader, signatureHeader, serviceToken.service)) {
      return res.status(401).json({ error: 'Invalid service signature' });
    }

    // Service can delegate user context for downstream operations
    if (serviceToken.delegatedUser) {
      (req as any).user = {
        userId: serviceToken.delegatedUser,
        role: serviceToken.delegatedRole || 'user',
        email: `${serviceToken.delegatedUser}@delegated.internal`,
        authenticatedVia: 'service-delegation',
        sourceService: serviceToken.service,
      };
    } else {
      (req as any).user = {
        userId: `svc:${serviceToken.service}`,
        role: 'service',
        email: null,
        authenticatedVia: 'service-direct',
        sourceService: serviceToken.service,
      };
    }
    return next();
  }

  if (authHeader?.startsWith('Bearer ')) {
    const token = authHeader.slice(7);
    try {
      const decoded = jwt.verify(token, JWT_SECRET) as UserToken;
      (req as any).user = {
        userId: decoded.userId,
        role: decoded.role,
        email: decoded.email,
        authenticatedVia: 'jwt',
        sourceService: null,
      };
      return next();
    } catch {
      return res.status(401).json({ error: 'Invalid JWT' });
    }
  }

  return res.status(401).json({ error: 'No authentication provided' });
}

// Authorization: check if user has required role
function requireRole(...roles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const user = (req as any).user;
    if (!user) return res.status(401).json({ error: 'Not authenticated' });

    // Service-delegated requests inherit the delegated role
    // Direct service calls get 'service' role which has elevated access
    const effectiveRole = user.role;

    if (roles.includes(effectiveRole)) {
      // For delegated auth, additionally validate delegation is allowed
      if (user.authenticatedVia === 'service-delegation') {
        const allowedDelegations: Record<string, string[]> = {
          'admin-panel': ['admin', 'moderator', 'user'],
          'mobile-gateway': ['user'],
          'user-service': ['user', 'moderator'],
        };
        const allowed = allowedDelegations[user.sourceService] || [];
        if (!allowed.includes(effectiveRole)) {
          return res.status(403).json({ error: 'Service not authorized to delegate this role' });
        }
      }
      return next();
    }

    return res.status(403).json({ error: 'Insufficient permissions' });
  };
}

// Admin endpoint: manage users
app.get('/api/admin/users', authenticate, requireRole('admin', 'service'), (req: Request, res: Response) => {
  res.json({ users: [{ id: '1', email: 'admin@example.com' }] });
});

// Admin endpoint: delete user
app.delete('/api/admin/users/:id', authenticate, requireRole('admin'), (req: Request, res: Response) => {
  const user = (req as any).user;
  // Audit log
  console.log(`User deletion by ${user.userId} via ${user.authenticatedVia} from ${user.sourceService}`);
  res.json({ deleted: req.params.id });
});

// User profile endpoint
app.get('/api/profile', authenticate, requireRole('user', 'admin', 'moderator'), (req: Request, res: Response) => {
  const user = (req as any).user;
  res.json({ userId: user.userId, role: user.role, email: user.email });
});

// Elevation request: user requests temporary admin for specific action
app.post('/api/elevate', authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  const { action, justification } = req.body;

  // Only service accounts from admin-panel can process elevation
  if (user.authenticatedVia !== 'service-delegation' || user.sourceService !== 'admin-panel') {
    return res.status(403).json({ error: 'Elevation only via admin-panel service' });
  }

  // Issue short-lived elevated token
  const elevatedToken = jwt.sign(
    { userId: user.userId, role: 'admin', email: user.email, elevated: true },
    JWT_SECRET,
    { expiresIn: '5m' }
  );

  res.json({ token: elevatedToken, expiresIn: 300 });
});

export default app;
